from pathlib import Path
root=Path(__file__).parent
outroot=root.parent if root.name=='verification' else root
engine=(root/'engines.mjs').read_text().replace('export function','function')
common_css='''
:root{--navy:#123044;--ink:#203847;--muted:#617581;--blue:#147d9c;--aqua:#d7eff0;--orange:#bb642e;--line:#d7e0e2;--paper:#f5f6f2;--red:#a12b35;--green:#226b51}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:15px/1.6 system-ui,-apple-system,Segoe UI,sans-serif}a{color:#076a85}header{background:var(--navy);color:#fff}header>div{max-width:1280px;margin:auto;padding:32px 26px 34px}.eyebrow{text-transform:uppercase;letter-spacing:.19em;font-size:11px;color:#a6d4da;font-weight:700}h1{font-size:clamp(27px,4vw,43px);line-height:1.15;max-width:850px;letter-spacing:-.03em;margin:13px 0}header p{margin:12px 0 0;max-width:850px;color:#d3e4e8}.nav{display:flex;gap:20px;flex-wrap:wrap;max-width:1280px;margin:auto;padding:13px 26px;border-bottom:1px solid var(--line);font-size:13px}.nav a{text-decoration:none}main{max-width:1280px;padding:24px 26px 45px;margin:auto}.layout{display:grid;grid-template-columns:340px minmax(0,1fr);gap:22px}.panel{background:#fff;border:1px solid var(--line);border-radius:12px;padding:22px;margin-bottom:18px}h2{font-size:19px;letter-spacing:-.02em;margin:0 0 15px}h3{font-size:15px;margin:21px 0 10px}.fields{display:grid;grid-template-columns:1fr 1fr;gap:12px}.field{display:flex;flex-direction:column;gap:4px}.field label{font-size:12px;line-height:1.4;color:#526876;min-height:32px}.field.full{grid-column:1/-1}input,select{width:100%;min-width:0;border:1px solid #adbdc4;border-radius:6px;font:inherit;background:#fff;padding:9px;color:var(--ink)}input:focus,select:focus{outline:3px solid #b9dee7;outline-offset:1px}button,.cta{font:600 13px/1.4 system-ui;display:inline-block;padding:11px 16px;border:0;border-radius:6px;background:var(--blue);color:#fff;text-decoration:none;cursor:pointer;margin:6px 5px 4px 0}button.secondary{background:#e7eef0;color:var(--ink)}button:disabled{opacity:.45;cursor:default}.cta{background:var(--navy)}.actions{margin-top:17px}.sub{font-size:12px;color:var(--muted)}.notice{padding:13px 15px;background:#fdf2e7;border-left:3px solid var(--orange);font-size:13px;border-radius:0 6px 6px 0;margin-top:16px}.error{color:var(--red);font-weight:600;font-size:13px}.stats{display:grid;grid-template-columns:repeat(3,1fr);gap:11px}.stat{border:1px solid var(--line);background:#f8faf9;border-radius:8px;padding:16px 13px}.stat span{display:block;font-size:11px;color:var(--muted);line-height:1.4;min-height:31px}.stat b{display:block;font-size:clamp(20px,2.3vw,30px);line-height:1.3;margin:7px 0;font-variant-numeric:tabular-nums}.stat small{font-size:11px;color:var(--muted)}.good{color:var(--green)}.bad{color:var(--red)}.badge{font-size:11px;letter-spacing:.08em;color:#17667c;font-weight:700}.tablewrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:12px}th,td{padding:10px 8px;border-bottom:1px solid var(--line);text-align:right;white-space:nowrap;font-variant-numeric:tabular-nums}th:first-child,td:first-child{text-align:left;white-space:normal}th{font-size:11px;color:var(--muted);font-weight:600;background:#f5f8f8}.formula{background:#f3f7f7;border-radius:7px;padding:15px;font-size:13px;line-height:1.9}.legend{display:flex;gap:17px;flex-wrap:wrap;font-size:11px;color:var(--muted)}.legend i{display:inline-block;width:14px;height:3px;vertical-align:middle;margin-right:5px}svg{width:100%;height:auto;display:block}details{margin-top:14px;font-size:13px}summary{cursor:pointer;font-weight:600}footer{max-width:1280px;padding:15px 26px 40px;margin:auto;font-size:12px;color:var(--muted)}.contact{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap;background:#dfedee;padding:22px;border-radius:9px;margin-top:20px}.contact h2{margin:0 0 5px}.contact p{font-size:13px;margin:0}.stamp{font-size:12px;color:var(--muted);margin-bottom:13px}.loading{color:var(--blue)}#outputs[hidden]{display:none}.sr{position:absolute;width:1px;height:1px;overflow:hidden;clip:rect(0,0,0,0)}@media(max-width:900px){.layout{grid-template-columns:1fr}.stats{grid-template-columns:repeat(3,1fr)}}@media(max-width:550px){main{padding:18px 14px}.panel{padding:17px}.stats{grid-template-columns:1fr}.stat span{min-height:0}.stat b{font-size:27px}.nav{gap:12px}header>div{padding:25px 18px}}@media print{header{background:#fff;color:#123044}header p,.eyebrow{color:#435966}header>div{padding:0}h1{font-size:24px}.nav,.controls,.contact,button,.no-print{display:none!important}.layout{display:block}body{background:#fff;font-size:10pt}main{padding:12px 0}.panel{padding:8px 0;border:0;break-inside:avoid;margin-bottom:12px}.stats{grid-template-columns:repeat(3,1fr)}table{font-size:8pt}th,td{padding:6px}svg{max-height:250px}.stat b{font-size:20px}footer{padding:0}#outputs[hidden]{display:none}@page{size:A4;margin:14mm}}
'''
common_js='''
const $=id=>document.getElementById(id),f=(v,d=2)=>Number.isFinite(v)?v.toLocaleString('ru-RU',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
function read(){const p={};document.querySelectorAll('[data-param]').forEach(el=>{if(el.tagName==='SELECT'&&el.id==='metal')p[el.id]=el.value;else{if(el.value.trim()==='')throw Error('Заполните поле: '+el.labels[0].textContent);p[el.id]=Number(el.value);if(!Number.isFinite(p[el.id]))throw Error('Введите конечное число');}});return p;}
function table(headers,rows){return '<div class="tablewrap"><table><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map(x=>'<td>'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
function stat(label,value,unit,cls=''){return `<div class="stat"><span>${label}</span><b class="${cls}">${value}</b><small>${unit}</small></div>`;}
function download(name,text,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\\ufeff'+text],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function lineChart(series,xTitle,yTitle,target=null){const all=series.flatMap(s=>s.data).filter(v=>Number.isFinite(v[1]));if(!all.length)return '';let xmin=Math.min(...all.map(v=>v[0])),xmax=Math.max(...all.map(v=>v[0])),ymin=Math.min(0,...all.map(v=>v[1])),ymax=Math.max(...all.map(v=>v[1]),target??-Infinity);if(ymin===ymax)ymax=ymin+1;const pad=(ymax-ymin)*.12;ymax+=pad;ymin-=pad;const X=x=>70+(x-xmin)/(xmax-xmin||1)*620,Y=y=>250-(y-ymin)/(ymax-ymin)*205;let s='<svg viewBox="0 0 740 310" role="img" aria-label="'+xTitle+'; '+yTitle+'"><rect width="740" height="310" fill="#fafcfb"/>';for(let i=0;i<5;i++){let y=ymin+(ymax-ymin)*i/4,x=xmin+(xmax-xmin)*i/4;s+=`<path d="M70 ${Y(y)}H690" stroke="#e0e7e7"/><text x="63" y="${Y(y)+4}" text-anchor="end" font-size="11" fill="#617581">${f(y,1)}</text><text x="${X(x)}" y="272" text-anchor="middle" font-size="11" fill="#617581">${f(x,0)}</text>`;}if(target!==null)s+=`<path d="M70 ${Y(target)}H690" stroke="#bb642e" stroke-dasharray="5 4"/>`;if(ymin<0&&ymax>0)s+=`<path d="M70 ${Y(0)}H690" stroke="#a9b9be"/>`;for(const a of series){let pen=false,path='';for(const pt of a.data){if(!Number.isFinite(pt[1])){pen=false;continue;}path+=(pen?'L':'M')+X(pt[0])+','+Y(pt[1]);pen=true;}s+=`<path d="${path}" fill="none" stroke="${a.color}" stroke-width="3"/>`;}return s+`<text x="70" y="24" font-size="12" fill="#425c67">${yTitle}</text><text x="385" y="301" text-anchor="middle" font-size="12" fill="#425c67">${xTitle}</text></svg>`;}
function clearError(){ $('error').textContent='';}
function printReport(){const details=[...document.querySelectorAll('details')],opened=details.map(d=>d.open);details.forEach(d=>d.open=true);window.print();details.forEach((d,i)=>d.open=opened[i]);}
'''
def field(k,label,value,minv=0,maxv=None,step='any',full=False):
 return f'<div class="field {"full" if full else ""}"><label for="{k}">{label}</label><input data-param id="{k}" type="number" value="{value}" min="{minv}" '+(f'max="{maxv}" ' if maxv is not None else '')+f'step="{step}" required></div>'
def wrap(title,eyebrow,desc,controls,output,js):
 return f'''<!doctype html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Eduard Kharitonov</title><meta name="description" content="{desc}"><meta property="og:title" content="{title}"><meta property="og:description" content="{desc}"><meta property="og:type" content="website"><style>{common_css}</style></head><body><header><div><span class="eyebrow">Independent Mining Engineering / interactive tools</span><h1>{title}</h1><p>{desc}</p></div></header><nav class="nav" aria-label="Инженерные программы"><a href="./">Скальный откос</a><a href="stope-economics.html">Экономика камеры</a><a href="dump-stability.html">Устойчивость отвала</a><a href="mailto:eduard@ugmineplanner.com">Связаться с инженером</a></nav><main><div class="layout"><aside class="controls"><section class="panel"><span class="badge">{eyebrow}</span><h2>Исходные данные</h2>{controls}<div id="error" class="error" role="alert"></div></section></aside><div><div id="state" class="panel loading" role="status" aria-live="polite">Подготовка расчёта…</div><div id="outputs" hidden>{output}</div><section class="contact"><div><h2>Нужен расчёт вашего проекта?</h2><p>Eduard Kharitonov · Mining Engineer / Geomechanics Specialist<br>Тбилиси · доступен для удалённого международного консалтинга и проектной работы</p></div><a class="cta" href="mailto:eduard@ugmineplanner.com?subject=Engineering%20project%20enquiry">Обсудить мой проект ↗</a></section></div></div></main><footer>Демонстрационный инструмент · условные данные · версия 1.0, 19.10.2026. Расчёт выполняется локально в браузере. Форма связи открывает вашу почтовую программу; исходные данные автоматически не отправляются.</footer><script>{engine}\n{common_js}\n{js}</script></body></html>'''
# Economics
fields='<div class="fields"><div class="field full"><label for="metal">Металл и единица содержания</label><select data-param id="metal"><option value="Au">Золото · Au, г/т · цена USD/oz</option><option value="Cu">Медь · Cu, % · цена USD/т металла</option></select></div>'
for a in [('length','Длина камеры, м',30,1,300),('width','Ширина, м',10,1,100),('height','Высота, м',25,1,200),('density','Плотность руды, т/м³',2.8,.1,10),('grade','Содержание Au, г/т',3,0,1000),('price','Цена Au, USD/oz',2500,.01,None),('loss','Потери руды, %',8,0,99.9),('dilution','Пустая порода / ROM, %',15,0,95),('recovery','Извлечение на фабрике, %',90,.01,100),('payability','Оплата извлечённого металла, %',95,.01,100),('mining','Добыча, USD/т ROM',35,0,None),('processing','Переработка и G&A, USD/т ROM',25,0,None),('wasteDensity','Плотность пустой породы, т/м³',2.6,.1,10),('backfill','Закладка, USD/м³ пустоты',12,0,None),('devLength','Отнесённая проходка, м',120,0,None),('devRate','Проходка, USD/м',2200,0,None),('fixed','Прочие отнесённые затраты, USD',50000,0,None)]:fields+=field(*a)
fields+='</div><p class="sub">Цены — условные примеры, не рыночная котировка. Пустая порода считается безрудной; потери равномерны по содержанию. Закладка: 100% расчётной пустоты.</p><div class="actions"><button id="calc">Рассчитать</button><button id="reset" class="secondary">Контрольный пример</button></div>'
output='''<section class="panel"><span class="badge">STOPE ECONOMICS / MATERIAL → METAL → MARGIN</span><h2>Результат камеры</h2><div id="stamp" class="stamp"></div><div id="stats" class="stats"></div><div id="conclusion" class="notice"></div></section><section class="panel"><h2>Баланс материала и металла</h2><div id="balance"></div><div id="flow"></div></section><section class="panel"><h2>Как разубоживание меняет маржу</h2><div id="chart"></div><div class="legend"><span><i style="background:#147d9c"></i>Заданные потери</span><span><i style="background:#bb642e"></i>Потери + 5 процентных пунктов</span></div><p class="sub">Геометрия, исходное содержание и цена фиксированы. Разубоживание — массовая доля безрудной породы в ROM. Маржа до налогов, финансирования и дисконтирования.</p></section><section class="panel"><h2>Сравнение вариантов</h2><div id="variants"></div></section><section class="panel"><h2>Затраты и проверяемые равенства</h2><div id="costs"></div><div id="checks"></div><details><summary>Методика, формулы и ограничения</summary><div class="formula">V = L × B × H; M₀ = Vρ<br>Mᵣ = M₀(1 − потери/100); Mп = Mᵣ·d/(1−d); ROM = Mᵣ + Mп<br>Содержание ROM = g·Mᵣ/ROM; d = разубоживание/100<br>Au: металл, oz = Mᵣ·g/31,1034768; Cu: металл, т = Mᵣ·g/100<br>Оплачиваемый металл = содержащийся × извлечение × оплата<br>Выручка = оплачиваемый металл × цена<br>Затраты = ROM·(добыча + переработка/G&A) + (Mᵣ/ρруды + Mп/ρпороды)·закладка + проходка·ставка + прочие<br>Маржа = выручка − затраты</div><p>Камера — прямоугольный расчётный объём, полностью занятый однородной рудой до потерь. Это технико-экономический скрининг одной камеры: устойчивость, допустимость размеров и календарь здесь не рассчитываются. Положительная маржа не означает готовность к отработке. Проходка и прочие затраты должны быть отнесены без двойного счёта. Не включены налоги, роялти, финансирование, график капитальных затрат и денежные потоки по периодам. NPV/IRR не рассчитываются. Предел разубоживания рассчитан только при неизменных цене, содержании и удельных затратах. Проектные нормативы и критерий FoS не применяются к этой арифметической модели.</p></details></section><section class="panel"><h2>Сохранить результат</h2><button id="print">Отчёт / PDF</button><button id="csv" class="secondary">Таблица CSV</button><p class="sub">Для PDF выберите «Сохранить как PDF» в окне печати. Отчёт включает текущие исходные данные и результаты.</p><div id="inputsReport"></div></section>'''
js='''
let current=null;const defaults=read();
function reset(){Object.entries(defaults).forEach(([k,v])=>$(k).value=v);metalLabels();calculate();}
function metalLabels(){const gold=$('metal').value==='Au';document.querySelector('label[for="grade"]').textContent=gold?'Содержание Au, г/т':'Содержание Cu, %';document.querySelector('label[for="price"]').textContent=gold?'Цена Au, USD/oz':'Цена Cu, USD/т металла';}
function calculate(){clearError();current=null;$('outputs').hidden=true;try{const p=read(),r=economics(p);current={p,r};const gold=p.metal==='Au',mu=gold?'oz Au':'т Cu',gu=gold?'г/т':'%';$('state').hidden=true;$('outputs').hidden=false;$('stamp').textContent='Рассчитано '+new Date().toLocaleString('ru-RU');$('stats').innerHTML=stat('Денежная маржа',f(r.margin,0),'USD на камеру',r.margin>=0?'good':'bad')+stat('Товарная горная масса',f(r.rom,0),'т ROM')+stat('Извлечённый металл',f(r.metal,2),mu)+stat('Выручка',f(r.revenue,0),'USD')+stat('Полные учтённые затраты',f(r.cost,0),'USD')+stat('Безубыточное исходное содержание',f(r.breakEvenGrade,3),gu);
$('conclusion').textContent=(r.margin>=0?'Положительная':'Отрицательная')+' маржа в заданных допущениях. '+(r.maxDilution===null?'Даже без разубоживания учтённые затраты не покрываются.':'Предел разубоживания при нулевой марже: '+f(r.maxDilution,1)+'% ROM.')+' Геомеханическая допустимость камеры не проверена.';
const rows=[['Геометрический объём',f(r.volume,2),'м³'],['Руда до потерь',f(r.ore,2),'т'],['Потери',f(r.lost,2),'т'],['Извлечённая руда',f(r.recoveredOre,2),'т'],['Безрудное разубоживание',f(r.waste,2),'т'],['ROM',f(r.rom,2),'т'],['Содержание ROM',f(r.romGrade,3),gu],['Металл в извлечённой руде',f(r.contained,3),mu],['Извлечённый металл после фабрики',f(r.metal,3),mu],['Оплачиваемый металл',f(r.payable,3),mu],['Расчётная пустота / закладка',f(r.excavation,2),'м³']];$('balance').innerHTML=table(['Показатель','Значение','Единица'],rows);
let data=[],other=[];for(let d=0;d<=60;d+=2){data.push([d,economics({...p,dilution:d}).margin/1000]);other.push([d,economics({...p,dilution:d,loss:Math.min(99,p.loss+5)}).margin/1000]);}$('chart').innerHTML=lineChart([{data,color:'#147d9c'},{data:other,color:'#bb642e'}],'Пустая порода / ROM, %','Денежная маржа, тыс. USD');
const variants=[['Без разубоживания',{...p,dilution:0}],['Текущий вариант',p],['Разубоживание +10 п.п.',{...p,dilution:Math.min(95,p.dilution+10)}],['Цена −20%',{...p,price:p.price*.8}]];$('variants').innerHTML=table(['Вариант','ROM, т','Содержание ROM, '+gu,'Металл, '+mu,'Маржа, USD'],variants.map(([name,v])=>{const q=economics(v);return [name,f(q.rom,0),f(q.romGrade,3),f(q.metal,2),f(q.margin,0)];}));
$('costs').innerHTML=table(['Статья','USD'],[['Добыча',f(r.rom*p.mining,2)],['Переработка и G&A',f(r.rom*p.processing,2)],['Закладка',f(r.excavation*p.backfill,2)],['Проходка',f(r.development,2)],['Прочие отнесённые затраты',f(p.fixed,2)],['Итого',f(r.cost,2)]]);$('checks').innerHTML=table(['Проверка','Невязка'],[['Руда₀ − извлечённая − потери, т',f(r.massResidual,8)],['ROM − руда − порода, т',f(r.romResidual,8)],['Выручка − затраты − маржа, USD',f(r.revenue-r.cost-r.margin,8)]]);$('inputsReport').innerHTML=table(['Исходные данные','Значение'],Object.entries(p).map(([k,v])=>[k==='metal'?'Металл':document.querySelector('label[for="'+k+'"]').textContent,typeof v==='number'?f(v,3):v]));
}catch(e){$('error').textContent=e.message;$('state').hidden=false;$('state').textContent='Расчёт не выполнен. Исправьте исходные данные.';}}
$('calc').onclick=calculate;$('reset').onclick=reset;$('metal').addEventListener('change',()=>{const g=$('metal').value==='Au';$('grade').value=g?3:1.2;$('price').value=g?2500:8500;metalLabels();calculate();});document.querySelectorAll('input[data-param]').forEach(el=>el.addEventListener('input',calculate));$('print').onclick=()=>{calculate();if(current)printReport();};$('csv').onclick=()=>{if(!current)return;const {p,r}=current;download('stope-economics.csv','Показатель;Значение\\n'+[...Object.entries(p),...Object.entries(r)].map(([k,v])=>k+';'+(typeof v==='number'?String(v).replace('.',','):v)).join('\\n'),'text/csv;charset=utf-8');};calculate();
'''
(outroot/'stope-economics.html').write_text(wrap('Экономика подземной камеры','01 / INPUTS','От геометрии и содержания — к ROM, извлекаемому металлу и денежной марже. Изменяйте параметры и сравнивайте решения.',fields,output,js))
# Dump
fields='<div class="fields">'
for a in [('H','Высота отвала H, м',30,1,200),('beta','Угол откоса β, °',32,10,60),('gamma','Объёмный вес γ, кН/м³',21,10,35),('c',"Сцепление c′, кПа",0,0,100),('phi',"Угол трения φ′, °",34,0,55),('water','Уровень воды у бровки, % H',65,0,80),('depth','Однородное основание, м',5,0,200),('q','Нагрузка на плато, кПа',0,0,500),('target','Условный критерий FoS',1.3,.1,5)]:fields+=field(*a)
fields+='</div><div class="notice">Однородный 2D откос с горизонтальным основанием. Глубина ниже подошвы моделируется тем же материалом; ниже — непроницаемая для поверхности скольжения граница. Критерий FoS задаёт пользователь, это не нормативное значение.</div><div class="actions"><button id="calc">Найти поверхности</button><button id="reset" class="secondary">Контрольный пример</button></div><p class="sub">После изменения данных нажмите «Найти поверхности». Все параметры — условные примеры.</p>'
output='''<section class="panel"><span class="badge">DUMP STABILITY / BISHOP SIMPLIFIED</span><h2>Минимум среди проверенных круговых поверхностей</h2><div id="stamp" class="stamp"></div><div id="stats" class="stats"></div><div id="conclusion" class="notice"></div></section><section class="panel"><h2>Разрез и найденная поверхность</h2><div id="geometry"></div><div class="legend"><span><i style="background:#bb642e"></i>Поверхность скольжения</span><span><i style="background:#147d9c"></i>Пьезометрическая линия</span><span><i style="background:#123044"></i>Откос</span></div><p class="sub">X и Z в метрах; одинаковый масштаб по осям. Показана нижняя дуга круга; не исследуются некруговые и трёхмерные механизмы.</p></section><section class="panel"><h2>Варианты инженерного решения</h2><div id="variants"></div><p class="sub">Для каждого варианта выполнен отдельный поиск. Дренаж условно представлен снижением пьезометрической линии вдвое, без расчёта фильтрации и производительности дрен.</p></section><section class="panel"><h2>Чувствительность к углу откоса</h2><div id="chart"></div><div class="legend"><span><i style="background:#147d9c"></i>Заданная вода</span><span><i style="background:#bb642e"></i>Пользовательский критерий FoS</span></div><p class="sub">Каждая точка — отдельный поиск с 60 исходными полосами. Основной поиск: 80 полос с добавлением границ плато и подошвы. Линия соединяет рассчитанные точки, не является проектной оптимизацией.</p></section><section class="panel"><h2>Проверка расчётного ядра и дискретизации</h2><div id="benchmark"></div><div id="mesh"></div><div id="searchInfo"></div><details><summary>Открыть формулы, источники и границы поиска</summary><div class="formula">F = Σ[(c′bᵢ + (Wᵢ − uᵢbᵢ)tan φ′) / mᵢ] / Σ[Wᵢ sin αᵢ]<br>mᵢ = cos αᵢ + sin αᵢ tan φ′ / F<br>Wᵢ = γAᵢ + q·bᵢ (q только на плато)<br>uᵢ = 9,81·max(0, zводы − zоснования), кПа<br>F находится итерациями; невязка ≤ 10⁻⁶·max(1,F)</div><p>Метод Бишопа: вертикальное равновесие полос и общее равновесие моментов, нулевые межполосные касательные силы. Пьезометрическая линия горизонтальна за бровкой и линейно снижается к подошве; внешнего водоёма нет. γ — постоянный заданный объёмный вес всего материала. Нагрузка q вертикальна, равномерна на плато в пределах искомой призмы.</p><p>Область поиска: вход от −2H до −0,005H; выход от 0,03B до B+0,5H; B=H·cot β. Центр лежит на верхнем перпендикуляре к хорде, отступ 0,02H…5H. Начальная сетка: 12×18×18, затем 4 локальных уточнения. Минимум относится только к проверенному семейству: полнота глобального поиска и независимая проверка геометрии не подтверждены. Круги выше поверхности, ниже заданного основания, с площадью &lt;0,002H², без сходимости или с отрицательной эффективной нормальной силой на полосе исключаются; число исключений по растяжению показано. Трещина отрыва отдельно не моделируется.</p><p>Не учитываются слоистость и слабое основание, анизотропия, сейсмика, разжижение, большие деформации, стадийность отсыпки, фильтрация и пространственный эффект. Для реального отвала требуется инженерно-геологическая модель и независимый расчёт. Это демонстрационный скрининг; нормативное соответствие не устанавливается.</p><p>Источники метода и контрольных чисел: Rocscience, <a href="https://static.rocscience.cloud/assets/verification-and-theory/Slide2/Hand-Calculation-1-Simple-Homogeneous-Dry-Slope.pdf" target="_blank" rel="noopener">Hand Calculation 1, Table 1 и уравнение (6), стр. 1–5</a>; <a href="https://static.rocscience.cloud/assets/verification-and-theory/Slide2/Hand-Calculation-2-Simple-Homogeneous-Wet-Slope.pdf" target="_blank" rel="noopener">Hand Calculation 2, Table 1/3 и уравнение (6), стр. 1–5</a>. Приведённые в источниках ответы округлены; заявленный там допуск итераций 0,005. Эти проверки относятся к заданным полосам, не к поиску критической поверхности.</p></details></section><section class="panel"><h2>Расчётные полосы найденного круга</h2><details><summary>Показать таблицу полос</summary><div id="slices"></div></details><button id="csv" class="secondary">Полосы CSV</button><button id="print">Отчёт / PDF</button><div id="inputsReport"></div></section>'''
worker=engine+'''\nonmessage=e=>{try{const p=e.data;const base=search(p),dry=search({...p,water:0}),drained=search({...p,water:p.water/2}),flat=search({...p,beta:Math.max(10,p.beta-5)});let curve=[];for(let i=0;i<7;i++){const beta=Math.max(10,p.beta-8)+(Math.min(60,p.beta+8)-Math.max(10,p.beta-8))*i/6;const s=search({...p,beta},60);curve.push([beta,s.best?s.best.F:null]);}const mesh=base.best?[40,80,160,320].map(n=>{const r=circle(p,base.best.entry,base.best.exit,base.best.offset,n);return [n,r?.F??null,r?.tension??false];}):[];postMessage({p,base,variants:[['Текущий вариант',base],['Сухой материал',dry],['Уровень воды / 2',drained],['Угол −5°',flat]],curve,mesh,bench:benchmarks()});}catch(e){postMessage({error:e.message});}};'''
import json
js='''
let current=null,worker=null,revision=0;const defaults=read();
function geometry(p,r){const B=p.H/Math.tan(p.beta*Math.PI/180),xmin=Math.min(-p.H*.8,r.entry-p.H*.1),xmax=Math.max(B+p.H*.4,r.exit+p.H*.1),zmin=-p.depth-p.H*.15,zmax=p.H*1.25;const scale=Math.min(620/(xmax-xmin),300/(zmax-zmin)),X=x=>65+(x-xmin)*scale,Z=z=>335-(z-zmin)*scale;let out='<svg viewBox="0 0 740 390" role="img" aria-label="Разрез отвала и найденная круговая поверхность"><rect width="740" height="390" fill="#fafcfb"/>';let arc=[];for(let i=0;i<=120;i++){const x=r.entry+(r.exit-r.entry)*i/120;arc.push([x,r.yc-Math.sqrt(Math.max(0,r.R*r.R-(x-r.xc)**2))]);}const coords=pts=>pts.map(pt=>X(pt[0])+','+Z(pt[1])).join(' ');const top=[[xmin,p.H],[0,p.H],[B,0],[xmax,0]];out+=`<polygon points="${coords([...top,[xmax,-p.depth],[xmin,-p.depth]])}" fill="#e0e9e5"/><polyline points="${coords(top)}" stroke="#123044" stroke-width="3" fill="none"/>`;let cap=[[r.entry,terrain(r.entry,p)]];if(r.entry<0&&r.exit>0)cap.push([0,p.H]);if(r.entry<B&&r.exit>B)cap.push([B,0]);cap.push([r.exit,terrain(r.exit,p)],...arc.slice().reverse());out+=`<polygon points="${coords(cap)}" fill="#bb642e" opacity=".15"/>`;for(let i=0;i<r.slices.length;i+=5){const s=r.slices[i];out+=`<path d="M${X(s.x)} ${Z(s.top)}V${Z(s.z)}" stroke="#bba38d" stroke-width="1"/>`;}out+=`<polyline points="${coords(arc)}" stroke="#bb642e" stroke-width="3" fill="none"/><polyline points="${coords([[xmin,water(xmin,p)],[0,water(0,p)],[B,0],[xmax,0]])}" stroke="#147d9c" stroke-width="2" stroke-dasharray="7 4" fill="none"/><path d="M${X(xmin)} ${Z(-p.depth)}H${X(xmax)}" stroke="#849898" stroke-dasharray="4 4"/>`;for(let i=0;i<=4;i++){const x=xmin+(xmax-xmin)*i/4,z=zmin+(zmax-zmin)*i/4;out+=`<text x="${X(x)}" y="360" text-anchor="middle" font-size="11" fill="#617581">${f(x,0)}</text><text x="55" y="${Z(z)+4}" text-anchor="end" font-size="11" fill="#617581">${f(z,0)}</text>`;}return out+`<text x="360" y="383" font-size="12">X, м</text><text x="12" y="22" font-size="12">Z, м</text><text x="${X(B)+8}" y="${Z(0)-9}" font-size="12">Подошва</text><text x="${X(0)}" y="${Z(p.H)-12}" font-size="12">H=${f(p.H,0)} м; β=${f(p.beta,1)}°</text></svg>`;}
function invalidate(){revision++;current=null;if(worker){worker.terminate();worker=null;}$('outputs').hidden=true;$('state').hidden=false;$('state').textContent='Данные изменены. Нажмите «Найти поверхности».';$('calc').disabled=false;clearError();}
function calculate(){invalidate();let p;try{p=read();searchCheck(p);}catch(e){$('error').textContent=e.message;return;}const token=revision;$('state').textContent='Идёт поиск круговых поверхностей и сравнение вариантов…';$('calc').disabled=true;const code=WORKERCODE;const url=URL.createObjectURL(new Blob([code],{type:'text/javascript'}));worker=new Worker(url);URL.revokeObjectURL(url);worker.onmessage=e=>{if(token!==revision)return;worker.terminate();worker=null;$('calc').disabled=false;if(e.data.error){$('error').textContent=e.data.error;$('state').textContent='Расчёт не выполнен.';return;}current=e.data;render(current);};worker.onerror=e=>{if(token!==revision)return;$('calc').disabled=false;$('error').textContent='Ошибка расчётного процесса. Повторите расчёт; данные не отправлялись.';$('state').textContent='Расчёт не выполнен.';worker?.terminate();worker=null;};worker.postMessage(p);}
function searchCheck(p){if(!(p.H>=1&&p.H<=200&&p.beta>=10&&p.beta<=60&&p.gamma>=10&&p.gamma<=35&&p.c>=0&&p.c<=100&&p.phi>=0&&p.phi<=55&&p.water>=0&&p.water<=80&&p.depth>=0&&p.depth<=p.H&&p.q>=0&&p.q<=500&&p.target>0))throw Error('Проверьте диапазоны. Глубина основания должна быть от 0 до H.');}
function render(d){const {p,base,variants,curve,mesh,bench}=d,r=base.best;const meshOk=mesh.length===4&&mesh.every(v=>Number.isFinite(v[1])&&!v[2])&&Math.abs(mesh[3][1]-mesh[2][1])/Math.max(Math.abs(mesh[3][1]),1e-12)<.005;$('state').hidden=true;$('outputs').hidden=false;$('stamp').textContent='Рассчитано '+new Date().toLocaleString('ru-RU');if(!r){$('stats').innerHTML=stat('Результат','HOLD','Допустимый круг не найден');$('conclusion').textContent='В заданной области поиска нет сошедшейся поверхности без растягивающих эффективных нормальных сил. Это не подтверждение устойчивости. Измените схему или выполните расширенный расчёт.';$('geometry').innerHTML='';}else{$('stats').innerHTML=stat('Коэффициент запаса',f(r.F,3),'Bishop Simplified',r.F>=p.target?'good':'bad')+stat('Площадь призмы',f(r.area,1),'м² на 1 м ширины')+stat('Проверенные круги',String(base.tested),'включая локальное уточнение');$('conclusion').textContent=(r.F>=p.target?'Пользовательский критерий достигнут':'Пользовательский критерий не достигнут')+'. Найденный минимум относится только к исследованным кругам. '+(base.boundary?'Минимум близок к границе поиска: требуется расширение области. ':'')+'Проектное заключение об устойчивости не выдаётся.';$('geometry').innerHTML=geometry(p,r);}
$('variants').innerHTML=table(['Вариант','FoS','Сопоставление с критерием'],variants.map(([name,v])=>[name,v.best?f(v.best.F,3):'HOLD',v.best?(v.best.F>=p.target?'≥ '+f(p.target,2):'< '+f(p.target,2)):'Нет допустимого круга']));$('chart').innerHTML=lineChart([{data:curve.map(([x,y])=>[x,y===null?NaN:y]),color:'#147d9c'}],'Угол откоса β, °','FoS, безразмерный',p.target);
$('benchmark').innerHTML=table(['Контроль ядра: заданные 7 полос','Расчёт','Источник','|Δ|','Допуск','Статус'],bench.map(b=>[b.wet?'Rocscience Hand Calculation 2':'Rocscience Hand Calculation 1',f(b.actual,6),f(b.expected,3),f(Math.abs(b.actual-b.expected),6),'0,005',b.pass?'PASS':'FAIL']));$('mesh').innerHTML=table(['Исходное число полос','FoS на том же круге','Растяжение N′'],mesh.map(([n,v,t])=>[n,v===null?'HOLD':f(v,6),t?'Есть · HOLD':'Нет']));const last=mesh.length?mesh[mesh.length-1][1]:null,previous=mesh.length?mesh[mesh.length-2][1]:null;const meshText=last!==null&&previous!==null?'Изменение FoS при 160 → 320 полосах: '+f(Math.abs(last-previous)/Math.max(Math.abs(last),1e-12)*100,3)+'%. ':'';$('searchInfo').innerHTML='<p class="sub">'+meshText+'Сошедшихся кругов: '+base.converged+'; исключено по N′ &lt; 0: '+base.tensionCount+'. '+(r?'Невязка уравнения F: '+r.residual.toExponential(2)+'. Центр ('+f(r.xc,3)+'; '+f(r.yc,3)+') м; R='+f(r.R,3)+' м.':'')+'</p>';
$('slices').innerHTML=r?table(['№','X, м','b, м','W, кН/м','u, кПа','α, °'],r.slices.map((s,i)=>[i+1,f(s.x,3),f(s.b,3),f(s.W,3),f(s.u,3),f(s.alpha*180/Math.PI,3)])):'';$('inputsReport').innerHTML=table(['Исходные данные','Значение'],Object.entries(p).map(([k,v])=>[document.querySelector('label[for="'+k+'"]').textContent,f(v,3)]));if(bench.some(b=>!b.pass)||!meshOk){$('conclusion').textContent='HOLD: контроль ядра, дискретизации или отсутствия растягивающих N′ не пройден. Численное FoS не использовать для вывода об устойчивости.';document.querySelectorAll('#stats .good').forEach(el=>el.className='bad');}}
$('calc').onclick=calculate;$('reset').onclick=()=>{Object.entries(defaults).forEach(([k,v])=>$(k).value=v);calculate();};document.querySelectorAll('input[data-param]').forEach(el=>el.addEventListener('input',invalidate));$('print').onclick=()=>{if(current)printReport();};$('csv').onclick=()=>{if(!current?.base.best)return;const r=current.base.best;download('dump-bishop-slices.csv','slice;x_m;b_m;W_kN_per_m;u_kPa;alpha_deg\\n'+r.slices.map((s,i)=>[i+1,s.x,s.b,s.W,s.u,s.alpha*180/Math.PI].join(';')).join('\\n'),'text/csv;charset=utf-8');};calculate();
'''.replace('WORKERCODE',json.dumps(worker,ensure_ascii=False))
(outroot/'dump-stability.html').write_text(wrap('Устойчивость отвала','01 / GEOMETRY & MATERIAL','Круговые поверхности, вода и геометрия откоса. Прозрачный расчёт по Бишопу с контрольными примерами и сравнением вариантов.',fields,output,js))
